  private calculate(type: string, current: Row[], previous: Row[], sourceCount: number, previousCount: number) { const insufficient = sourceCount < 3; const delta = sourceCount - previousCount; const direction = insufficient ? 'Insufficient Data' : previousCount === 0 ? (sourceCount ? 'New Issue' : 'Stable') : delta < 0 ? 'Improving' : delta > 0 ? 'Worsening' : 'Stable'; const confidence = insufficient ? 'Insufficient Data' : sourceCount >= 20 ? 'High' : sourceCount >= 8 ? 'Medium' : 'Low'; const severity = !insufficient && (direction === 'Worsening' || direction === 'New Issue') && current.some((row) => this.isCritical(row.criticality ?? row.event_severity)) ? 'Critical' : direction === 'Worsening' ? 'High' : 'Informational'; const result = { result_type: type, result_title: type, result_description: insufficient ? 'Insufficient source records for a reliable trend. No conclusion is shown.' : `${sourceCount} scoped source event(s) compared with ${previousCount}.`, source_record_count: sourceCount, metric_key: 'event_count', metric_value: sourceCount, previous_metric_value: previousCount, trend_direction: direction, trend_confidence: confidence, severity, criticality: current.some((row) => this.isCritical(row.criticality ?? row.event_severity)) ? 'Critical' : null, explanation_json: { sourceCount, previousCount, delta, directionRule: 'backend event-count comparison', note: 'Trend analysis is governance intelligence and not legal certification.' } }; return { direction, confidence, severity, summary: { sourceCount, previousCount, delta, direction, confidence, severity }, results: [result] }; }
